import os
import time

from FlagEmbedding import FlagReranker

# 模型路径基于文件位置解析，避免受启动目录影响
CURRENT_DIR = os.path.dirname(os.path.abspath(__file__))
PARENT_DIR = os.path.dirname(CURRENT_DIR)
RERANKER_PATH = os.path.join(PARENT_DIR, "Qwen", "bge-reranker-base")


def LoadReranker():
    reranker = FlagReranker(RERANKER_PATH, use_fp16=True)
    return reranker

def Reranker(reranker, query, relative_knowledge):

    # 计算每个相对知识与查询的评分
    scores = []
    for knowledge in relative_knowledge:
        score = reranker.compute_score([query, knowledge])
        scores.append((knowledge, score))

    # 按照分数进行排序，获取前五个最高分的元素
    top_five = sorted(scores, key=lambda x: x[1], reverse=True)[:5]

    # 创建一个只包含知识的字典列表
    result = [{knowledge} for knowledge, score in top_five]

    # 打印最相似的前五个知识
    for item in result:
        print(f"Knowledge: {item}")

    return result  # 返回包含知识的字典列表


